17	)
18	
19	type ArenaProxyHandler struct {
20		socketPath string
21		logger     *zap.Logger
22		client     *http.Client
23	}
24	
25	func NewArenaProxyHandler(socketPath string, logger *zap.Logger) *ArenaProxyHandler {
26		if logger == nil {
27			logger = zap.NewNop()
28		}
29	
30		// Create HTTP client that connects via Unix socket
31		client := &http.Client{
32			Timeout: 30 * time.Second,
33			Transport: &http.Transport{
34				DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
35					return net.Dial("unix", socketPath)
36				},
37			},
38		}
39	
40		return &ArenaProxyHandler{
41			socketPath: socketPath,
42			logger:     logger,
43			client:     client,
44		}
45	}
46	
47	// RegisterRoutes registers the arena proxy routes
48	func (h *ArenaProxyHandler) RegisterRoutes(router interface {
49		HandleFunc(string, func(http.ResponseWriter, *http.Request)) *mux.Route
50		Handle(string, http.Handler) *mux.Route
51	}) {
52		// Register all /arena/* paths to be proxied to the KNIRVARENA service
53		// Use a route that catches all arena paths
54		muxRouter, ok := router.(*mux.Router)
55		if !ok {
56			h.logger.Warn("Arena proxy handler: router is not a *mux.Router, falling back to HandleFunc")
57			if handleFunc, ok := router.(interface {
58				HandleFunc(string, func(http.ResponseWriter, *http.Request)) *mux.Route
59			}); ok {
60				handleFunc.HandleFunc("/arena", h.handleArenaRoot)
61				handleFunc.HandleFunc("/arena/", h.handleArenaRoot)
62			}
63			return
64		}
65	
66		// Mount all arena routes with a path prefix
67		arenaRouter := muxRouter.PathPrefix("/arena").Subrouter()
68		arenaRouter.HandleFunc("", h.handleArenaRoot).Methods("GET", "HEAD")
69		arenaRouter.HandleFunc("/", h.handleArenaRoot).Methods("GET", "HEAD")
70		arenaRouter.PathPrefix("/").HandlerFunc(h.handleArenaProxy)
71	
72		h.logger.Info("Arena proxy routes registered", zap.String("socket_path", h.socketPath))
73	}
74	
75	// handleArenaRoot handles the root /arena path
76	func (h *ArenaProxyHandler) handleArenaRoot(w http.ResponseWriter, r *http.Request) {
77		h.proxyRequest(w, r, "/")
78	}
79	
80	// handleArenaProxy proxies all /arena/* requests to the KNIRVARENA service
81	func (h *ArenaProxyHandler) handleArenaProxy(w http.ResponseWriter, r *http.Request) {
82		// Extract the path after /arena and proxy it
83		path := r.URL.Path
84		if strings.HasPrefix(path, "/arena") {
85			path = strings.TrimPrefix(path, "/arena")
86			if path == "" {
87				path = "/"
88			}
89		}
90		h.proxyRequest(w, r, path)
91	}
92	
93	// proxyRequest proxies the HTTP request to the KNIRVARENA service via Unix socket
94	func (h *ArenaProxyHandler) proxyRequest(w http.ResponseWriter, r *http.Request, path string) {
95		// Build the target URL (localhost is used because we connect via Unix socket)
96		targetURL := fmt.Sprintf("http://localhost%s", path)
97		if r.URL.RawQuery != "" {
98			targetURL = fmt.Sprintf("%s?%s", targetURL, r.URL.RawQuery)
99		}
100	
101		// Create a new request to the backend service
102		proxyReq, err := http.NewRequestWithContext(r.Context(), r.Method, targetURL, r.Body)
103		if err != nil {
104			h.logger.Error("Failed to create proxy request", zap.Error(err), zap.String("path", path))
105			http.Error(w, "Failed to proxy request", http.StatusInternalServerError)
106			return
107		}
108	
109		// Copy headers from the original request
110		proxyReq.Header = make(http.Header)
111		for key, values := range r.Header {
112			// Skip certain headers that should not be proxied
113			if shouldSkipHeader(key) {
114				continue
115			}
116			for _, value := range values {
117				proxyReq.Header.Add(key, value)
118			}
119		}
120	
121		// Set the Host header to the target service
122		proxyReq.Host = "localhost"
123	
124		// Execute the proxy request
125		resp, err := h.client.Do(proxyReq)
126		if err != nil {
127			h.logger.Error("Arena proxy request failed",
128				zap.Error(err),
129				zap.String("path", path),
130				zap.String("method", r.Method),
131			)
132			http.Error(w, "Failed to reach arena service", http.StatusBadGateway)
133			return
134		}
135		defer resp.Body.Close()
136	
137		// Copy response headers
138		for key, values := range resp.Header {
139			for _, value := range values {
140				w.Header().Add(key, value)
141			}
142		}
143	
144		// Write the status code
145		w.WriteHeader(resp.StatusCode)
146	
147		// Copy the response body
148		if _, err := io.Copy(w, resp.Body); err != nil {
149			h.logger.Error("Failed to copy response body", zap.Error(err), zap.String("path", path))
150			// Response header already written, so we can't send error
151			return
152		}
153	
154		h.logger.Debug("Arena proxy request completed",
155			zap.String("path", path),
156			zap.String("method", r.Method),
157			zap.Int("status", resp.StatusCode),
158		)
159	}
160	
161	// shouldSkipHeader returns true if the header should not be proxied
162	func shouldSkipHeader(key string) bool {
163		skipHeaders := []string{
164			"Connection",
165			"Keep-Alive",
166			"Proxy-Authenticate",
167			"Proxy-Connection",
168			"TE",
169			"Trailers",
170			"Transfer-Encoding",
171			"Upgrade",
172		}
173		for _, skip := range skipHeaders {
174			if strings.EqualFold(key, skip) {
175				return true
176			}
177		}
178		return false
179	}
