390	// extractBinaries extracts all embedded binaries to the app data bin directory.
391	// Returns the bin directory path.
392	func extractBinaries() (string, error) {
393		appDataDir, err := getAppDataDir()
394		if err != nil {
395			return "", fmt.Errorf("failed to get app data directory: %w", err)
396		}
397	
398		binDir := filepath.Join(appDataDir, "bin")
399		if err := os.MkdirAll(binDir, 0755); err != nil {
400			return "", fmt.Errorf("failed to create bin directory: %w", err)
401		}
402	
403		decompressed, err := decompressBinary(backendBinary)
404		if err != nil {
405			return "", fmt.Errorf("failed to decompress backend binary: %w", err)
406		}
407	
408		type entry struct {
409			name string
410			data []byte
411		}
412		bins := []entry{
413			{"backend_server", decompressed},
414		}
415	
416		for _, b := range bins {
417			dest := filepath.Join(binDir, b.name)
418			if err := os.RemoveAll(dest); err != nil {
419				return "", fmt.Errorf("failed to remove existing %s: %w", b.name, err)
420			}
421			if err := writeFileAtomically(dest, b.data, 0755); err != nil {
422				return "", fmt.Errorf("failed to extract %s: %w", b.name, err)
423			}
424			log.Printf("Extracted %s to %s", b.name, dest)
425		}
426	
427		return binDir, nil
428	}
