530	// extractEnvFile extracts the embedded environment file based on the specified environment
531	func extractEnvFile(environment string) error {
532		var envData []byte
533		var envName string
534	
535		switch environment {
536		case "development":
537			envData = envDevelopment
538			envName = ".env.development"
539		case "testnet":
540			envData = envTestnet
541			envName = ".env.testnet"
542		case "production":
543			// For production, we expect the .env file to be provided externally
544			// or configured through environment variables
545			log.Println("Production mode: skipping .env file extraction (use external .env or environment variables)")
546			return nil
547		default:
548			return fmt.Errorf("unknown environment: %s (must be development, testnet, or production)", environment)
549		}
550	
551		// Extract to app data directory so the application can find it.
552		appDataDir, err := getAppDataDir()
553		if err != nil {
554			return fmt.Errorf("failed to get app data directory: %w", err)
555		}
556		envPath := filepath.Join(appDataDir, ".env")
557		if err := writeFileAtomically(envPath, envData, 0644); err != nil {
558			return fmt.Errorf("failed to write %s to %s: %w", envName, envPath, err)
559		}
560	
561		// Propagate the path so subprocesses can locate it.
562		os.Setenv("KNIRV_ENV_FILE", envPath)
563	
