591	// extractConfigFiles extracts embedded config files to the canonical config directory.
592	func extractConfigFiles() error {
593		configDir, err := getExtractedConfigDir()
594		if err != nil {
595			return err
596		}
597	
598		// Walk through embedded config files
599		err = fs.WalkDir(configFiles, "config", func(path string, d fs.DirEntry, err error) error {
600			if err != nil {
601				return err
602			}
603	
604			// Skip directories
605			if d.IsDir() {
606				return nil
607			}
608	
609			// Read embedded file
610			data, err := configFiles.ReadFile(path)
611			if err != nil {
612				return fmt.Errorf("failed to read embedded file %s: %w", path, err)
613			}
614	
615			// Extract just the filename (remove "config/" prefix)
616			filename := filepath.Base(path)
617			destPath := filepath.Join(configDir, filename)
618	
619			// Write to local filesystem
620			if err := writeFileAtomically(destPath, data, 0644); err != nil {
621				return fmt.Errorf("failed to write config file %s: %w", destPath, err)
622			}
623	
624			log.Printf("Extracted config file: %s", destPath)
625			return nil
626		})
627	
628		return err
629	}
