809						if err := app.upd.TriggerUpdate(); err != nil {
810							log.Printf("[updater] apply error: %v", err)
811						}
812					}()
813					return
814				}
815	
816				// Detect network-monitor paths and proxy to the gateway instead
817				// of the backend, since the gateway has Go handler equivalents.
818				if strings.HasPrefix(c.Request.URL.Path, "/api/network-monitor/") {
819					nmProxy, nmErr := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
820					if nmErr == nil {
821						nmProxy.ServeHTTP(c.Writer, c.Request)
822						return
823					}
824				}
825				// Per-DVE agent API: /api/agent/{dveId}/... → KNIRVGATEWAY dynamicAgentProxy
826				// (cannot register as a named Gin route; /api/*path catch-all owns the prefix)
827				if strings.HasPrefix(c.Request.URL.Path, "/api/agent/") {
828					agentProxy, agentErr := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
829					if agentErr == nil {
830						agentProxy.ServeHTTP(c.Writer, c.Request)
831						return
832					}
833				}
834				// Construct backend URL
835				backendURL := backendBaseURL(app.config) + c.Request.RequestURI
836				transport := &http.Transport{}
837				if app.config.BackendSocket != "" {
838					transport = unixSocketTransport(app.config.BackendSocket)
839				}
840	
841				// Create proxy request
842				req, err := http.NewRequest(c.Request.Method, backendURL, c.Request.Body)
843				if err != nil {
844					c.JSON(500, gin.H{"error": "Failed to create proxy request"})
845					return
846				}
847	
848				// Copy headers
849				for key, values := range c.Request.Header {
850					for _, value := range values {
851						req.Header.Add(key, value)
852					}
853				}
854	
855				// Detect SSE requests: no Timeout so streaming connections are never killed.
856				isSSE := strings.Contains(c.GetHeader("Accept"), "text/event-stream") ||
857					c.Request.URL.Query().Get("stream") == "1"
858	
859				var client *http.Client
860				if isSSE {
861					client = &http.Client{
862						Transport: transport,
863						CheckRedirect: func(req *http.Request, via []*http.Request) error {
864							return http.ErrUseLastResponse
865						},
866					}
867				} else {
868					client = &http.Client{
869						Timeout:   60 * time.Second,
870						Transport: transport,
871						CheckRedirect: func(req *http.Request, via []*http.Request) error {
872							return http.ErrUseLastResponse
873						},
874					}
875				}
876	
877				resp, err := client.Do(req)
878				if err != nil {
879					log.Printf("Proxy error: %v", err)
880					c.JSON(http.StatusServiceUnavailable, gin.H{"error": "Backend service unavailable"})
881					return
882				}
883				defer resp.Body.Close()
884	
885				// Copy response headers
886				for key, values := range resp.Header {
887					for _, value := range values {
888						c.Header(key, value)
889					}
890				}
891	
892				// For SSE responses flush each chunk immediately; otherwise buffer normally.
893				c.Status(resp.StatusCode)
894				if strings.Contains(resp.Header.Get("Content-Type"), "text/event-stream") {
895					flusher, canFlush := c.Writer.(http.Flusher)
896					buf := make([]byte, 4096)
897					for {
898						n, readErr := resp.Body.Read(buf)
899						if n > 0 {
900							c.Writer.Write(buf[:n]) //nolint:errcheck
901							if canFlush {
902								flusher.Flush()
903							}
904						}
905						if readErr != nil {
906							break
907						}
908					}
909				} else {
910					io.Copy(c.Writer, resp.Body) //nolint:errcheck
911				}
912			})
913		}
