957		wsProxy := &httputil.ReverseProxy{
958			Director: func(req *http.Request) {
959				req.URL.Scheme = backendWS.Scheme
960				req.URL.Host = backendWS.Host
961			},
962			Transport: wsTransport,
963		}
964		wsProxy.FlushInterval = -1 // flush immediately; required for streaming / WebSocket
965		wsProxy.ErrorHandler = func(w http.ResponseWriter, r *http.Request, err error) {
966			// The error handler is only invoked before the connection is hijacked,
967			// so it is safe to write an HTTP error response here.
968			log.Printf("WebSocket proxy error for %s: %v", r.URL.Path, err)
969			http.Error(w, "WebSocket backend unavailable", http.StatusBadGateway)
970		}
971	
972		wsHandler := func(c *gin.Context) {
973			// All WebSocket paths — including /ws/dve/{dveId}/inner/* for inner agent PTY
974			// streams — are handled by the backend subprocess (gorilla/mux), which has the
975			// DVEInnerAgentWSHandler registered and connects directly to per-DVE sockets.
976			wsProxy.ServeHTTP(c.Writer, c.Request)
977		}
