981		// Serve embedded frontend files.
982		// Before falling through to the main frontend static files, check if
983		// the request is a dynamic asset load from the gateway SPA (identified
984		// by a Referer header pointing to a gateway route).  The gateway's
985		// Next.js app lazy-loads route chunks with hardcoded /_next/ paths
986		// that our HTML rewrite cannot intercept — these arrive here via NoRoute.
987		app.router.NoRoute(func(c *gin.Context) {
988			// If the Referer indicates this is a sub-request from the gateway
989			// SPA (e.g. a dynamically-imported page chunk), proxy it through
990			// the gateway's Unix socket so it gets the correct asset.
991			if referer := c.GetHeader("Referer"); referer != "" {
992				refURL, err := url.Parse(referer)
993				if err == nil && (strings.HasPrefix(refURL.Path, "/gateway") ||
994					refURL.Path == "/dashboard" ||
995					refURL.Path == "/chain-explorer" ||
996					refURL.Path == "/graph-explorer" ||
997					refURL.Path == "/error-explorer") {
998					gwProxy, gwErr := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
999					if gwErr == nil {
1000						gwProxy.ServeHTTP(c.Writer, c.Request)
1001						return
1002					}
1003				}
1004			}
1005			// Proxy known gateway SPA routes through the gateway at the same path,
1006			// preserving the route so the WebGUI loads the correct page.  The
1007			// gateway serves individual HTML pages (dashboard.html, etc.) with
1008			// injected __GATEWAY_BASE__ config.  Using the same path avoids the
1009			// "always shows /explorer" problem that a blanket redirect to /gateway
1010			// would cause.
1011			path := c.Request.URL.Path
1012			if path == "/dashboard" || path == "/chain-explorer" || path == "/graph-explorer" || path == "/error-explorer" {
1013				gwProxy, gwErr := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
1014				if gwErr == nil {
1015					gwProxy.ServeHTTP(c.Writer, c.Request)
1016					return
1017				}
1018			}
1019			embeddedFS.ServeHTTP(c.Writer, c.Request)
1020		})
1021	
1022		return nil
1023	}
