1025	// killStaleBackend sends SIGTERM then SIGKILL to any running backend_server processes
1026	// so port 4001 (P2P/libp2p) and other ports are free before a new instance starts.
1027	func killStaleBackend(binaryPath string) {
1028		binaryName := filepath.Base(binaryPath)
1029		if binaryName == "" || binaryName == "." {
1030			binaryName = "backend_server"
1031		}
1032		if cmd := exec.Command("pkill", "-TERM", "-x", binaryName); cmd.Run() == nil {
1033			time.Sleep(2 * time.Second)
1034		}
1035		exec.Command("pkill", "-KILL", "-x", binaryName).Run() //nolint:errcheck
1036	}
