1038	// waitForPortFreeMain blocks until the given TCP port is no longer occupied or the deadline.
1039	func waitForPortFreeMain(port int, deadline time.Duration) bool {
1040		end := time.Now().Add(deadline)
1041		for time.Now().Before(end) {
1042			ln, err := net.Listen("tcp", fmt.Sprintf(":%d", port))
1043			if err == nil {
1044				ln.Close()
1045				return true
1046			}
1047			time.Sleep(300 * time.Millisecond)
1048		}
1049		return false
1050	}
