1052	// startBackend starts the embedded unified backend service
1053	func (app *ServerApp) startBackend() error {
1054		if app.config.BackendSocket != "" {
1055			log.Printf("Starting unified backend service on socket %s...", app.config.BackendSocket)
1056		} else {
1057			log.Printf("Starting unified backend service on port %d...", app.config.BackendPort)
1058		}
1059	
1060		// Kill any stale backend_server processes from previous runs so they do not
1061		// hold the P2P port (4001) or other resources that would cause the new
1062		// instance to crash on startup.
1063		log.Println("Killing any stale backend_server processes...")
1064		killStaleBackend(app.backendPath)
1065		if !waitForPortFreeMain(4001, 8*time.Second) {
1066			log.Println("Warning: P2P port 4001 still occupied after kill — proceeding anyway")
1067		}
1068	
1069		// Pass the config file path used by the wrapper to the backend.
1070		// This ensures the backend uses the same configuration.
1071		configFile := viper.ConfigFileUsed()
1072		if configFile != "" {
1073			log.Printf("Passing config file to backend: %s", configFile)
1074			app.backendCmd = exec.Command(app.backendPath, "--config", configFile)
1075		} else {
1076			app.backendCmd = exec.Command(app.backendPath)
1077		}
