1079		// Set environment variables for backend
1080		env := append(os.Environ(),
1081			fmt.Sprintf("KNIRV_API_PORT=%d", app.config.BackendPort),
1082			fmt.Sprintf("KNIRV_API_SOCKET=%s", app.config.BackendSocket),
1083			fmt.Sprintf("KNIRV_API_SOCKET_PATH=%s", app.config.BackendSocket),
1084			fmt.Sprintf("KNIRV_CONFIG_FILE=%s", configFile),
1085			"KNIRV_API_HOST=127.0.0.1",
1086			"REDACTED",
1087			"REDACTED",
1088			"KNIRV_SECURITY_AUTH_REQUIRED=false",
1089		)
