1091		// Propagate paths to bundled binaries so the backend does not rely on CWD
1092		// or system PATH to locate knirvgateway and knirvshell.  Also propagate the
1093		// app data directory so the gateway runtime extracts files there instead of
1094		// /tmp, and so the backend can locate config/log directories consistently.
1095		if appDataDir, err := getAppDataDir(); err == nil {
1096			binDir := filepath.Join(appDataDir, "bin")
1097			env = append(env,
1098				fmt.Sprintf("KNIRV_APP_DATA_DIR=%s", appDataDir),
