1101				fmt.Sprintf("KNIRV_CHAIN_BINARY_DIR=%s", binDir),
1102				fmt.Sprintf("KNIRV_GRAPH_BINARY_DIR=%s", binDir),
1103				fmt.Sprintf("KNIRV_ORACLE_BINARY_DIR=%s", binDir),
1104				fmt.Sprintf("KNIRV_KNIRVCLI_PATH=%s", filepath.Join(binDir, "knirvshell")),
1105				fmt.Sprintf("KNIRV_ARENA_SOCKET_PATH=%s", filepath.Join(appDataDir, "sockets", "arena.sock")),
1106			)
1107		}
1108		if configDir, err := getConfigDir(); err == nil {
1109			env = append(env, fmt.Sprintf("KNIRV_CONFIG_DIR=%s", configDir))
1110		}
1111	
1112		// Pass the project log directory as an absolute path so the backend writes
1113		// logs to <cwd>/logs/server.log regardless of where the backend binary runs from.
1114		if cwd, err := os.Getwd(); err == nil {
1115			env = append(env, fmt.Sprintf("KNIRV_PROJECT_LOG_DIR=%s", filepath.Join(cwd, "logs")))
1116		}
