1118		// Add testnet environment variable if enabled
1119		if app.config.Testnet {
1120			env = append(env,
1121				"KNIRV_TESTNET=true",
1122				"KNIRV_SECURITY_AUTH_REQUIRED=false",
1123				"KNIRV_MODE=headless",
1124			)
1125			log.Println("Starting backend in testnet mode with simplified security")
1126		}
