1128		// Propagate ORACLE_KEY_PASSWORD from the parent environment so the
1129		// backend_server subprocess can decrypt root.key without needing an
1130		// interactive terminal.  Without this the backend silently skips all
1131		// root.key secrets (API keys for Gemini, DeepSeek, Cerebras, etc.).
1132		if pwd := os.Getenv("ORACLE_KEY_PASSWORD"); pwd != "" {
1133			env = append(env, fmt.Sprintf("ORACLE_KEY_PASSWORD=%s", pwd))
1134		}
1135	
1136		app.backendCmd.Env = env
1137		app.backendCmd.Stdout = os.Stdout
1138		app.backendCmd.Stderr = os.Stderr
1139	
1140		if err := app.backendCmd.Start(); err != nil {
1141			return fmt.Errorf("failed to start unified backend: %w", err)
1142		}
1143	
1144		log.Printf("Unified backend started (PID: %d)", app.backendCmd.Process.Pid)
1145	
1146		// Wait for backend to accept connections on its health endpoint.
1147		var healthURL string
1148		var client *http.Client
1149	
1150		if app.config.BackendSocket != "" {
1151			healthURL = "http://localhost/health"
1152			client = &http.Client{
1153				Timeout:   2 * time.Second,
1154				Transport: unixSocketTransport(app.config.BackendSocket),
1155			}
1156		} else {
1157			healthURL = fmt.Sprintf("http://localhost:%d/health", app.config.BackendPort)
1158			client = &http.Client{Timeout: 2 * time.Second}
1159		}
1160	
1161		deadline := time.Now().Add(30 * time.Second)
1162		for time.Now().Before(deadline) {
1163			resp, err := client.Get(healthURL)
1164			if err == nil {
1165				resp.Body.Close()
1166				if resp.StatusCode < 500 {
1167					if app.config.BackendSocket != "" {
1168						log.Printf("Backend ready on socket %s", app.config.BackendSocket)
1169					} else {
1170						log.Printf("Backend ready on port %d", app.config.BackendPort)
1171					}
1172					return nil
1173				}
1174			}
1175			time.Sleep(500 * time.Millisecond)
1176		}
1177		log.Printf("Warning: backend did not become healthy within 30s — proceeding anyway")
1178	
1179		return nil
1180	}
1181	
1182	// stopBackend stops the unified backend service
1183	func (app *ServerApp) stopBackend() {
1184		if app.backendCmd != nil && app.backendCmd.Process != nil {
1185			pid := app.backendCmd.Process.Pid
1186			log.Printf("Stopping unified backend (PID: %d)", pid)
1187	
1188			// Send SIGTERM for graceful shutdown
1189			if err := app.backendCmd.Process.Signal(syscall.SIGTERM); err != nil {
1190				log.Printf("Failed to signal backend PID %d: %v — force killing", pid, err)
1191				app.backendCmd.Process.Kill()
1192				app.backendCmd.Wait() // reap the zombie
1193				return
1194			}
1195	
1196			// Wait with a timeout, then escalate to SIGKILL.
1197			// Without this timeout a stuck backend would block shutdown forever.
1198			done := make(chan error, 1)
1199			go func() { done <- app.backendCmd.Wait() }()
1200			select {
1201			case err := <-done:
1202				if err != nil {
1203					log.Printf("Backend PID %d stopped: %v", pid, err)
1204				} else {
1205					log.Printf("Backend PID %d stopped gracefully", pid)
1206				}
1207			case <-time.After(30 * time.Second):
1208				log.Printf("Backend PID %d did not stop within 30s — sending SIGKILL", pid)
1209				app.backendCmd.Process.Kill()
1210				// Wait briefly for the goroutine to reap the zombie.
1211				select {
1212				case <-done:
1213				case <-time.After(2 * time.Second):
1214					log.Printf("Warning: backend PID %d Wait() did not complete after Kill() — zombie possible", pid)
1215				}
1216				log.Printf("Backend PID %d force killed", pid)
1217			}
1218		}
1219	}
1220	
1221	// Start starts the KNIRV-SERVER application
1222	func (app *ServerApp) Start() error {
1223		// Start backend first
1224		if err := app.startBackend(); err != nil {
1225			return err
1226		}
1227	
1228		// Create HTTP server
1229		// WriteTimeout is 0 (disabled) so SSE and long-lived streaming responses are
1230		// not killed by the server. ReadTimeout still guards against slow-loris attacks.
1231		app.server = &http.Server{
1232			Addr:        fmt.Sprintf("%s:%d", app.config.Host, app.config.Port),
1233			Handler:     app.router,
1234			ReadTimeout: 15 * time.Second,
1235			IdleTimeout: 120 * time.Second,
1236		}
1237	
1238		// Start server in goroutine
1239		go func() {
1240			log.Printf("Starting KNIRV-SERVER on %s:%d", app.config.Host, app.config.Port)
1241			if err := app.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
1242				log.Fatalf("Failed to start server: %v", err)
1243			}
1244		}()
1245	
1246		// Wait for server to be ready
1247		time.Sleep(2 * time.Second)
1248	
1249		return nil
1250	}
1251	
1252	// Stop stops the KNIRV-SERVER application
1253	func (app *ServerApp) Stop() error {
1254		// Stop HTTP server
1255		if app.server != nil {
1256			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
1257			defer cancel()
1258	
1259			if err := app.server.Shutdown(ctx); err != nil {
1260				log.Printf("Server shutdown error: %v", err)
1261			}
1262		}
1263	
1264		// Stop backend
1265		app.stopBackend()
1266	
1267		// Clean up temp directory
1268		if app.tempDir != "" {
1269			os.RemoveAll(app.tempDir)
1270		}
1271	
1272		return nil
1273	}
1274	
1275	// isFlagSet checks if a flag was explicitly set on the command line
1276	func isFlagSet(name string) bool {
1277		found := false
1278		flag.Visit(func(f *flag.Flag) {
1279			if f.Name == name {
1280				found = true
1281			}
1282		})
1283		return found
1284	}
1285	
1286	// loadConfig loads configuration from file and environment
1287	func loadConfig() (*Config, error) {
1288		// Parse command line flags
1289		var (
1290			configFile  = flag.String("config", "", "Path to configuration file")
1291			testnet     = flag.Bool("testnet", false, "Enable testnet mode")
1292			environment = flag.String("env", "development", "Environment: development, testnet, or production")
1293			port        = flag.Int("port", 0, "Server port (overrides config)")
1294			host        = flag.String("host", "", "Server host (overrides config)")
1295		)
1296		flag.Parse()
1297	
1298		// Check for KNIRV_ENV environment variable if --env flag not explicitly set
1299		if !isFlagSet("env") {
1300			if envVar := os.Getenv("KNIRV_ENV"); envVar != "" {
1301				*environment = envVar
1302				log.Printf("Using environment from KNIRV_ENV: %s", *environment)
1303			}
1304		}
1305	
1306		// Extract environment file based on flag or environment variable
1307		if err := extractEnvFile(*environment); err != nil {
1308			log.Printf("Warning: Failed to extract environment file: %v", err)
1309		}
1310	
1311		// Set config file if provided
1312		if *configFile != "" {
1313			viper.SetConfigFile(*configFile)
1314		} else {
1315			// Set config file name based on environment
1316			viper.SetConfigName(*environment)
1317			viper.SetConfigType("yaml")
1318	
1319			// Add canonical config directory first (highest priority)
1320			if configDir, err := getExtractedConfigDir(); err == nil {
1321				viper.AddConfigPath(configDir)
1322			}
1323	
1324			// Add local paths as fallback
1325			viper.AddConfigPath("./config")
1326			viper.AddConfigPath(".")
1327		}
1328	
1329		// Set default values
1330		viper.SetDefault("host", "0.0.0.0")
1331		viper.SetDefault("port", 8090)
1332		viper.SetDefault("backend_port", 8082)
1333		if appDataDir, err := getAppDataDir(); err == nil {
1334			viper.SetDefault("backend_socket", filepath.Join(appDataDir, "sockets", "backend.sock"))
1335			viper.SetDefault("gateway_socket", filepath.Join(appDataDir, "sockets", "gateway.sock"))
1336		}
1337		viper.SetDefault("gateway_port", 8080)
1338		viper.SetDefault("log_level", "info")
1339		viper.SetDefault("testnet", false)
1340	
1341		// Enable environment variable support
1342		viper.AutomaticEnv()
1343		viper.SetEnvPrefix("NEXUS")
1344	
1345		// Try to read config file
1346		if err := viper.ReadInConfig(); err != nil {
1347			if _, ok := err.(viper.ConfigFileNotFoundError); !ok {
1348				return nil, fmt.Errorf("error reading config file: %w", err)
1349			}
1350			log.Println("No config file found, using defaults and environment variables")
1351		}
1352	
1353		var config Config
1354		if err := viper.Unmarshal(&config); err != nil {
1355			return nil, fmt.Errorf("error unmarshaling config: %w", err)
1356		}
1357	
1358		// Initialize BackendSocket if empty
1359		if config.BackendSocket == "" {
