1366			if config.GatewaySocket == "" {
1367				if appDataDir, err := getAppDataDir(); err == nil {
1368					config.GatewaySocket = filepath.Join(appDataDir, "sockets", "gateway.sock")
1369				}
1370			}
1371		}
1372		if config.GatewayPort == 0 {
1373			config.GatewayPort = viper.GetInt("gateway.port")
1374			if config.GatewayPort == 0 {
1375				config.GatewayPort = 8080
1376			}
1377		}
1378	
1379		// Override with command line flags
1380		if *testnet {
1381			config.Testnet = true
1382		}
1383		if *port != 0 {
1384			config.Port = *port
1385		}
1386		if *host != "" {
