    topLevelAwait({
      promiseExportName: '__tla',
      promiseImportName: i => `__tla_${i}`
    }),
    ...(process.env.ANALYZE === 'true' ? [visualizer()] : [])
  ],

  esbuild: {},

  // Use absolute base for development stability
  base: '/',

