      'crypto': resolve(__dirname, 'src/shims/node-crypto.ts'),
      'jsonwebtoken': resolve(__dirname, 'src/shims/jsonwebtoken.ts')
    }
  },

  // Optimization
  optimizeDeps: {
    include: [
      'react',
      'react-dom',
      'react-router-dom',
      'lucide-react',
      '@tensorflow/tfjs',
      'three',
      '@react-three/fiber',
