1	package knirvarena
2	
3	import (
4		"context"
5		"crypto/sha1"
6		"encoding/base64"
7		"fmt"
8		"net"
9		"net/http"
10		"os"
11		"path/filepath"
12		"sync"
13		"time"
14	
15		"go.uber.org/zap"
16	)
17	
18	type ManagerConfig struct {
19		SocketPath   string
20		ExtractPath  string
21		StartTimeout time.Duration
22		StopTimeout  time.Duration
23	}
24	
25	type Manager struct {
26		config      *ManagerConfig
27		logger      *zap.Logger
28		server      *http.Server
29		listener    net.Listener
30		extractPath string
31		mu          sync.RWMutex
32		running     bool
33	}
34	
35	type HealthStatus struct {
36		Status      string    `json:"status"`
37		Running     bool      `json:"running"`
38		SocketPath  string    `json:"socket_path"`
39		ExtractPath string    `json:"extract_path"`
40		Timestamp   time.Time `json:"timestamp"`
41	}
42	
43	func getAppDataDir() string {
44		if explicit := os.Getenv("KNIRV_APP_DATA_DIR"); explicit != "" {
45			return explicit
46		}
47		if err := os.MkdirAll("/var/lib/knirvserver", 0755); err == nil {
48			return "/var/lib/knirvserver"
49		}
50		if home, err := os.UserHomeDir(); err == nil {
51			return filepath.Join(home, ".local", "share", "knirvserver")
52		}
53		return "data"
54	}
55	
56	func DefaultConfig() *ManagerConfig {
57		appDataDir := getAppDataDir()
58		return &ManagerConfig{
59			SocketPath:   filepath.Join(appDataDir, "sockets", "arena.sock"),
60			ExtractPath:  filepath.Join(appDataDir, "knirvarena"),
61			StartTimeout: 10 * time.Second,
62			StopTimeout:  10 * time.Second,
63		}
64	}
65	
66	func NewManager(cfg *ManagerConfig, logger *zap.Logger) *Manager {
67		if cfg == nil {
68			cfg = DefaultConfig()
69		}
70		if logger == nil {
71			logger, _ = zap.NewProduction()
72		}
73		return &Manager{
74			config: cfg,
75			logger: logger,
76		}
77	}
78	
79	func (m *Manager) Extract() (string, error) {
80		extractPath, err := ExtractEmbeddedApp(m.config.ExtractPath)
81		if err != nil {
82			return "", fmt.Errorf("failed to extract arena bundle: %w", err)
83		}
84		m.extractPath = extractPath
85		m.logger.Info("KNIRVARENA bundle extracted", zap.String("path", extractPath))
86		return extractPath, nil
87	}
88	
89	func (m *Manager) Start() error {
90		m.mu.Lock()
91		defer m.mu.Unlock()
92	
93		if m.running {
94			m.logger.Info("KNIRVARENA already running")
95			return nil
96		}
97	
98		if _, err := m.Extract(); err != nil {
99			return err
100		}
101	
102		socketDir := filepath.Dir(m.config.SocketPath)
103		if err := os.MkdirAll(socketDir, 0755); err != nil {
104			return fmt.Errorf("failed to create socket directory: %w", err)
105		}
106	
107		if err := os.Remove(m.config.SocketPath); err != nil && !os.IsNotExist(err) {
108			m.logger.Warn("Failed to remove stale socket", zap.String("path", m.config.SocketPath), zap.Error(err))
109		}
110	
111		listener, err := net.Listen("unix", m.config.SocketPath)
112		if err != nil {
113			return fmt.Errorf("failed to listen on Unix socket %s: %w", m.config.SocketPath, err)
114		}
115		if err := os.Chmod(m.config.SocketPath, 0777); err != nil {
116			listener.Close()
117			return fmt.Errorf("failed to chmod socket: %w", err)
118		}
119		m.listener = listener
120	
121		mux := http.NewServeMux()
122	
123		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
124			w.Header().Set("Content-Type", "application/json")
125			w.WriteHeader(http.StatusOK)
126			fmt.Fprintf(w, `{"status":"healthy","service":"knirvarena","timestamp":"%s"}`, time.Now().UTC().Format(time.RFC3339))
127		})
128	
129		mux.HandleFunc("/ws", m.handleWebSocket)
130	
131		fileServer := http.FileServer(http.Dir(m.extractPath))
132		mux.Handle("/", fileServer)
133	
134		m.server = &http.Server{
135			Handler:      mux,
136			ReadTimeout:  15 * time.Second,
137			WriteTimeout: 15 * time.Second,
138			IdleTimeout:  60 * time.Second,
139		}
140	
141		go func() {
142			m.logger.Info("KNIRVARENA server started on Unix socket", zap.String("socket", m.config.SocketPath))
143			if err := m.server.Serve(listener); err != nil && err != http.ErrServerClosed {
144				m.logger.Error("KNIRVARENA server error", zap.Error(err))
145			}
146		}()
147	
148		m.running = true
149	
150		go func() {
151			if !m.waitForHealth(m.config.StartTimeout) {
152				m.logger.Warn("KNIRVARENA did not become healthy within timeout")
153				return
154			}
155			m.logger.Info("KNIRVARENA health check passed")
156		}()
157	
158		return nil
159	}
160	
161	func (m *Manager) handleWebSocket(w http.ResponseWriter, r *http.Request) {
162		if r.Header.Get("Upgrade") != "websocket" {
163			http.Error(w, "not a websocket request", http.StatusBadRequest)
164			return
165		}
166	
167		hj, ok := w.(http.Hijacker)
168		if !ok {
169			http.Error(w, "hijacking not supported", http.StatusInternalServerError)
170			return
171		}
172		conn, bufrw, err := hj.Hijack()
173		if err != nil {
174			http.Error(w, err.Error(), http.StatusInternalServerError)
175			return
176		}
177		defer conn.Close()
178	
179		m.logger.Info("KNIRVARENA WebSocket connection established",
180			zap.String("remote", conn.RemoteAddr().String()))
181	
182		bufrw.WriteString("HTTP/1.1 101 Switching Protocols\r\n")
183		bufrw.WriteString("Upgrade: websocket\r\n")
184		bufrw.WriteString("Connection: Upgrade\r\n")
185		bufrw.WriteString("Sec-WebSocket-Accept: " + computeAcceptKey(r.Header.Get("Sec-WebSocket-Key")) + "\r\n")
186		bufrw.WriteString("\r\n")
187		bufrw.Flush()
188	
189		buf := make([]byte, 4096)
190		for {
191			n, err := conn.Read(buf)
192			if err != nil {
193				break
194			}
195			conn.Write(buf[:n])
